      "source": "// Reference File Manager Pro script (LANG-13):\n// - RPC handlers with cursor pagination for UI operations (\"listSorted\", \"planRename\", \"applyRenamePage\")\n// - Service watcher using on(\"fs.change\", ...) and emit(\"watcher.summary\", ...)\n\nimport { sortEntries, planBatchRename, summarizeChanges } from \"./file-manager-utils.puls\";\n\nvar watcherQueue = [];\n\nregisterHandler(\"listSorted\", function(path, by, asc) {\n  var raw = fsList(path);\n  return sortEntries(raw, by, asc);\n});\n\nregisterHandler(\"planRename\", function(dirPath, findStr, replaceStr, prefix) {\n  var raw = fsList(dirPath);\n  var all = planBatchRename(dirPath, raw, findStr, replaceStr, prefix);\n  return arrayFilter(all, function(item) { return item.changed; });\n});\n\nregisterHandler(\"applyRenamePage\", function(plan, cursor, pageSize) {\n  var total = len(plan);\n  var start = cursor < 0 ? 0 : cursor;\n  var end = start + pageSize;\n  if (end > total) end = total;\n  var slice = arraySlice(plan, start, end);\n  var moved = 0;\n  for (var item of slice) {\n    if (fsRename(item.from, item.to)) {\n      moved = moved + 1;\n    }\n  }\n  return {\n    moved: moved,\n    nextCursor: end,\n    done: end >= total\n  };\n});\n\non(\"fs.change\", function(ev) {\n  watcherQueue[len(watcherQueue)] = ev;\n  if (ev.flush || len(watcherQueue) >= 4) {\n    var summary = summarizeChanges(watcherQueue);\n    watcherQueue = [];\n    emit(\"watcher.summary\", summary);\n  }\n});",
